fn is_digit(c: Str) -> Bool {
  return c == "0" or c == "1" or c == "2" or c == "3" or c == "4" or c == "5" or c == "6" or c == "7" or c == "8" or c == "9"
}

fn amount(s: Str) -> Option[Int] {
  if s.is_empty() or (not (s.chars().all(fn(c) => is_digit(c)))) {
    return None
  }
  let v = s.to_int().unwrap_or(0)
  if v > 0 {
    return Some(v)
  }
  return None
}

fn apply_op(accounts: Map[Str, Int], op: Str) -> Result[Map[Str, Int], Str] {
  let parts = op.split(" ")
  let kind = parts.get_or(0, "")
  let a = parts.get_or(1, "")
  if kind == "open" and parts.len() == 2 {
    if accounts.has(a) {
      return Err("exists {a}")
    }
    return Ok(accounts.set(a, 0))
  }
  if kind == "dep" and parts.len() == 3 {
    let n = amount(parts.get_or(2, "")).ok_or("bad op")?
    if not (accounts.has(a)) {
      return Err("unknown {a}")
    }
    return Ok(accounts.set(a, accounts.get(a).unwrap_or(0) + n))
  }
  if kind == "wd" and parts.len() == 3 {
    let n = amount(parts.get_or(2, "")).ok_or("bad op")?
    if not (accounts.has(a)) {
      return Err("unknown {a}")
    }
    let bal = accounts.get(a).unwrap_or(0)
    if bal < n {
      return Err("insufficient {a}")
    }
    return Ok(accounts.set(a, bal - n))
  }
  if kind == "move" and parts.len() == 4 {
    let b = parts.get_or(2, "")
    let n = amount(parts.get_or(3, "")).ok_or("bad op")?
    if not (accounts.has(a)) {
      return Err("unknown {a}")
    }
    if not (accounts.has(b)) {
      return Err("unknown {b}")
    }
    let bal = accounts.get(a).unwrap_or(0)
    if bal < n {
      return Err("insufficient {a}")
    }
    let after_take = accounts.set(a, bal - n)
    return Ok(after_take.set(b, after_take.get(b).unwrap_or(0) + n))
  }
  return Err("bad op")
}

pub fn ledger(ops: List[Str]) -> Result[Map[Str, Int], Str] {
  var accounts: Map[Str, Int] = Map {}
  for op in ops {
    accounts = apply_op(accounts, op)?
  }
  return Ok(accounts)
}
